/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight auto
 * @framerIntrinsicWidth 1440
 */
export default function NoireProjectPage(props: { page?: string; style?: CSSProperties }) {
    const sections = PAGES[props.page ?? "quiet-matter"] ?? PAGES["quiet-matter"]
    return (
        <div style={{ ...props.style, width: "100%", display: "flex", flexDirection: "column" }}>
            {sections.map((s, i) => {
                const Section = C[s.name]
                return <Section key={i} {...s.props} />
            })}
        </div>
    )
}

addPropertyControls(NoireProjectPage, {
    page: { type: ControlType.Enum, title: "Page", options: ["quiet-matter","tidewater","ninefold","lowlight","field-notes-on-clay","index-of-rooms","the-long-table","paper-weather"], defaultValue: "quiet-matter" },
})
